inline const neocortex::protocol::WireEnvelope *GetWireEnvelope(const void *buf) {
  return ::flatbuffers::GetRoot<neocortex::protocol::WireEnvelope>(buf);
}

inline const neocortex::protocol::WireEnvelope *GetSizePrefixedWireEnvelope(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<neocortex::protocol::WireEnvelope>(buf);
}

inline const char *WireEnvelopeIdentifier() {
  return "NCPR";
}

inline bool WireEnvelopeBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, WireEnvelopeIdentifier());
}

inline bool SizePrefixedWireEnvelopeBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, WireEnvelopeIdentifier(), true);
}

